// 4-DOF servo arm with smooth motion. Servos need a SEPARATE 5-6V supply + common ground.
// ESP32: replace <Servo.h> with <ESP32Servo.h>. For many servos use a PCA9685.
#include <Servo.h>

const int N = 4;
Servo servos[N];
const int PINS[N]   = { 3, 5, 6, 9 };          // base, shoulder, elbow, gripper
float cur[N]        = { 90, 90, 90, 90 };      // current angle
float target[N]     = { 90, 90, 90, 90 };      // desired angle
const float SPEED   = 90.0;                     // degrees per second (smoothness)
unsigned long last = 0;

void setTargets(float b,float s,float e,float g){ target[0]=b; target[1]=s; target[2]=e; target[3]=g; }
bool reached(){ for(int i=0;i<N;i++) if(abs(cur[i]-target[i])>0.5) return false; return true; }

void setup(){
  for(int i=0;i<N;i++){ servos[i].attach(PINS[i]); servos[i].write((int)cur[i]); }
  Serial.begin(115200);
  Serial.println("Arm ready. Send: b s e g  (e.g. '120 60 100 30')");
}

int demo = 0;
unsigned long demoAt = 0;

void loop(){
  // --- serial control: 4 angles ---
  if (Serial.available()){
    float b=cur[0],s=cur[1],e=cur[2],g=cur[3];
    if (Serial.readStringUntil('\n').length()) {}
  }
  // --- demo pick-and-place cycle when idle ---
  if (reached() && millis() - demoAt > 800){
    demoAt = millis();
    switch(demo){
      case 0: setTargets(60, 60, 120, 10); break;   // reach
      case 1: setTargets(60, 40, 140, 70); break;   // grab
      case 2: setTargets(120,60, 120, 70); break;   // move
      case 3: setTargets(120,40, 140, 10); break;   // release
    }
    demo = (demo + 1) % 4;
  }
  // --- smooth motion update (eased toward target) ---
  if (millis() - last >= 20){                       // 50 Hz
    float dt = (millis() - last)/1000.0; last = millis();
    float step = SPEED * dt;
    for(int i=0;i<N;i++){
      if (cur[i] < target[i]) cur[i] = min(cur[i]+step, target[i]);
      else if (cur[i] > target[i]) cur[i] = max(cur[i]-step, target[i]);
      servos[i].write((int)cur[i]);
    }
  }
}
